# -*- coding: utf-8 -*-
"""Breath, parasite, movement, health, cloud, cube and taste lessons. No images."""
import json
from pathlib import Path
from lesson_authoring import entry as E
OUT=Path('.cache/batch200/drafts/rewrite_st');OUT.mkdir(parents=True,exist_ok=True)
ASSIGN=json.loads(Path('.cache/batch200/rewrite_st.json').read_text())
HAL=[['拉丁 halare 呼吸；inhalare 向……呼气','拉丁 in- 原有向着、在……上等义；英语这里发展为吸入']]
INHALE=HAL+[['英语先有 inhalation；后出现 inhale','可分析为从名词反构，或受法语 inhaler 及英语 exhale 的对应关系影响']]
VAD=[['拉丁 vadere 走、前进','复合词的过去分词词干可见 vas-，如 evas-、invas-']]
EVA=VAD+[['拉丁 e-／ex- 向外 + vadere → evadere','走出去，脱离、逃开']]
EVASIVE=EVA+[['拉丁 evas- → 法语 évasif → 英语 evasive','回避、躲开的；后来也说躲闪动作']]
INV=VAD+[['拉丁 in- 向内 + vadere → invadere','进入，进而有闯入、袭击的意思']]
SAL=[['拉丁 salus，属格 salutis','健康、安好、福祉']]
W=[
E('inhale','/ɪnˈheɪl/','吸入；吸气；狼吞虎咽地吃','气息往身体里面走；口语里吃得极快，也可以夸张地说像把饭吸了进去。','今天可理解为 in- 向内与呼吸词族相配。历史上 inhalation 先出现，inhale 可能由它反构，或经法语 inhaler、仿照 exhale 形成；不能只写成现代动词先加后缀变名词。',INHALE,'inhale smoke 是把烟吸进去，inhale deeply 是深吸气。inhale a sandwich 是轻松夸张的吃法描写，并非真的把整块食物吸入气管。','inhale deeply；inhale fumes；inhale a meal。','breathe 可以包括吸气和呼气；inhale 只指向内，exhale 指向外。食物义近似 gobble 或 wolf down，通常是口语。',('She inhaled slowly before beginning the song.','她开始唱歌前缓缓吸了一口气。'),('We inhaled our sandwiches and hurried back to the station.','我们三两口吃完三明治，赶回车站。'),sources=['https://www.etymonline.com/word/inhale','https://www.merriam-webster.com/dictionary/inhale','https://www.oxfordlearnersdictionaries.com/definition/english/inhale']),
E('inhalation','/ˌɪnhəˈleɪʃən/','吸入；吸气','把吸进去这件事当作一个过程来谈，尤其常见于烟尘、气体和吸入给药的描述。','外形可认出 inhale 与 -ation，但英语名词更早。它接拉丁 inhalare 的分词词干构成行动名词；拉丁原有向……呼气义，在英语中用于吸入。',HAL+[['拉丁 inhalare 的分词词干 → 英语 inhalation','十七世纪已有吸入义，早于英语动词 inhale']],'smoke inhalation 是吸入烟雾，inhalation of dust 是吸入粉尘。复数 inhalations 可以逐次计数每一口吸气，通常名词单数则指整个过程。','smoke inhalation；inhalation of fumes；by inhalation。','inhalation 是气息或物质随呼吸进入；ingestion 是吞食进入消化道。两者不是同一种进入身体的方式。',('The report linked the incident to the inhalation of smoke.','报告把这次事故与吸入烟雾联系起来。'),('The recording marks each inhalation with a soft sound.','录音用一个轻柔的声音标记每一次吸气。'),sources=['https://www.etymonline.com/word/inhalation','https://www.oxfordlearnersdictionaries.com/definition/english/inhalation']),
E('inhaler','英 /ɪnˈheɪlə/；美 /ɪnˈheɪlər/','吸入器','一种把药物随吸气送入呼吸道的装置，日常尤其常见于哮喘相关语境。','inhale + -er，去掉末尾不发音的 e 再加后缀；这里的 -er 指工具，不是吸气的人。',INHALE+[['英语 inhale + -er → inhaler','用于吸入的装置名称']],'an asthma inhaler 是哮喘吸入器；a pocket inhaler 强调小巧便携。不同装置有不同原理，这个总称本身不说明具体药品或用法。','an asthma inhaler；a reliever inhaler；carry an inhaler。','inhaler 是装置，inhalant 是吸入的物质。nebulizer 通常把液体变成可吸入的细雾，是另一类具体设备名称。',('She keeps her inhaler in the front pocket of her bag.','她把吸入器放在包的前袋里。'),('The leaflet includes a diagram of the inhaler.','说明单里有一幅吸入器示意图。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/inhaler','https://www.etymonline.com/word/inhale']),
E('inhalant','/ɪnˈheɪlənt/','吸入剂；被吸入的物质；供吸入的','把注意力放在吸进去的东西上，例如吸入用药物；一些语境也指被滥用的挥发性物质。','现代可认 inhale 与 -ant；历史还直接接拉丁 inhalant-，是 inhalare 的现在分词词干。英语先有供吸入的形容词，再有物质名称。',HAL+[['拉丁 inhalant- → 英语 inhalant 形容词 → 名词','用于吸入的 → 被吸入的制剂或物质']],'a medicinal inhalant 是吸入用药；inhalant abuse 讨论吸入性物质滥用。词义取决于上下文，不能看到它就一律译成吸入器。','a medicinal inhalant；inhalant use；inhalant abuse。','inhaler 是设备，inhalant 是物质；inhalation 是吸入行为。三者分别回答用什么装置、吸什么、做什么。',('The catalogue lists the product as a medicinal inhalant.','目录把这种产品列为药用吸入剂。'),('The survey includes a section on inhalant abuse.','调查中有一部分涉及吸入性物质滥用。'),sources=['https://www.etymonline.com/word/inhalant','https://www.oxfordlearnersdictionaries.com/definition/english/inhalant']),
E('inhalable','/ɪnˈheɪləbəl/','可吸入的；能随呼吸进入的','空气中的一些小颗粒能跟着气流进入鼻子或嘴，这就可以说是 inhalable。','inhale + -able，去掉末尾 e；后缀表示能够被……。这里的能够只是物理上能进入，不表示适合或安全。',INHALE+[['英语 inhale + -able → inhalable','能够随呼吸吸入的']],'inhalable dust 常出现在工作场所空气检测中；它不要求所有颗粒都进入肺的最深处。术语 respirable dust 通常特指能深入肺部某些区域的颗粒部分。','inhalable dust；inhalable particles；an inhalable formulation。','inhalable 说能被吸入；breathable air 常说空气适合呼吸。可吸入的粉尘并不因此变成可安全呼吸的东西。',('The laboratory measured inhalable dust near the cutting machine.','实验室测量了切割机附近的可吸入粉尘。'),('The researchers compared an inhalable formulation with a tablet.','研究人员比较了一种吸入制剂与一种片剂。'),sources=['https://www.collinsdictionary.com/dictionary/english/inhalable','https://en.wiktionary.org/wiki/inhalable#English','https://www.gov.uk/guidance/monitoring-ambient-air-particulate-matter']),
E('evade','/ɪˈveɪd/','躲避；逃避；回避','本来朝你来的追捕、问题或责任，被你想办法绕开了。','经法语 évader 接拉丁 evadere：e-／ex- 向外 + vadere 走。先抓住走出去、逃开的画面，再理解回避责任或问题。',EVA+[['法语 evader → 英语 evade','逃脱；后来强调巧妙避开']],'evade capture 是逃过抓捕，evade a question 是不正面回答。evade responsibility 是逃避责任；法律语境的 evade taxes 指逃税，不是泛指一切节税安排。','evade capture；evade a question；evade responsibility。','avoid 范围很广；evade 常带主动绕开、使对方抓不住的感觉。elude 还可说答案、名字等一时想不起来或无法获得。',('The runner changed direction to evade his pursuer.','那名奔跑者改变方向，躲开追赶他的人。'),('She evaded the question by talking about next year’s plans.','她转而谈明年的计划，回避了这个问题。'),sources=['https://www.etymonline.com/word/evade','https://www.oxfordlearnersdictionaries.com/definition/english/evade']),
E('evasion','/ɪˈveɪʒən/','逃避；回避；遁词','不是正面处理，而是找出口、绕过去；也可以指一句绕开重点的话。','与 evade 同接 evadere，但英语名词更早。来自晚期拉丁 evasio、evasion-，经法语或直接借入；不是英语 evade 后来才加 -sion。',EVA+[['晚期拉丁 evasio／evasion- → 法语 évasion／英语 evasion','出去、逃脱的行动；继而用于逃避和托词']],'evasion of responsibility 是逃避责任；一连串 evasions 可以是几次含糊其辞的回答。tax evasion 是固定的逃税说法。','tax evasion；evasion of responsibility；a series of evasions。','evasion 可以是一项逃避行为，也可以是一句遁词；evasiveness 更强调一个人或答复总不肯直接表态的特点。',('The interview was full of evasions and vague promises.','那场采访充满了回避和含糊的承诺。'),('The audit uncovered evidence of tax evasion.','审计发现了逃税的证据。'),sources=['https://www.etymonline.com/word/evasion','https://www.oxfordlearnersdictionaries.com/definition/english/evasion']),
E('evasive','/ɪˈveɪsɪv/','回避的；闪烁其词的；躲闪的','你想抓住一个明确答案，对方却总从旁边滑开；也可以说身体或车辆在躲避危险。','接法语 évasif，往前是拉丁 evadere 的 evas- 分词词干。现代与 evade 联系着记，但不是把英语 d 任意改成 s。',EVASIVE,'an evasive answer 是不正面回答；evasive action 是为躲避碰撞或攻击而采取的动作。前者常带批评，后者可以是必要的应对。','an evasive answer；be evasive about something；take evasive action。','vague 只说不清楚，未必故意；evasive 往往让人感觉对方在有意避开。evasive action 则不一定涉及说谎。',('He became evasive when we asked who had approved the payment.','我们问是谁批准付款时，他开始闪烁其词。'),('The pilot took evasive action to avoid the other aircraft.','飞行员采取躲避动作，避开另一架飞机。'),sources=['https://www.etymonline.com/word/evasive','https://www.oxfordlearnersdictionaries.com/definition/english/evasive']),
E('evasively','/ɪˈveɪsɪvli/','闪烁其词地；回避地','描述一次回答的方式：说了话，却没有把对方真正要问的事交代出来。','evasive + -ly；保留形容词 evasive，接方式副词后缀。',EVASIVE+[['英语 evasive + -ly → evasively','以回避、躲闪的方式']],'answer evasively 和 reply evasively 最自然。它强调绕开重点的方式，而不是声音小、语速慢或措辞客气。','answer evasively；reply evasively；speak evasively about something。','hesitantly 是犹豫地，可能只是没想好；evasively 通常提示不愿正面回答。两种表现可以同时出现，但意思不同。',('Asked about the missing money, he replied evasively.','被问到失踪的款项时，他含糊其词地回答。'),('She spoke evasively about why the meeting had been cancelled.','她对会议为何取消说得躲躲闪闪。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/evasively','https://www.etymonline.com/word/evasive']),
E('evasiveness','/ɪˈveɪsɪvnəs/','闪烁其词；回避的态度','让人觉得怎么问都抓不到实话的那种表现或态度。','evasive + -ness；将回避的特点变成通常不可数的名词。',EVASIVE+[['英语 evasive + -ness → evasiveness','回避、躲闪的特点或表现']],'his evasiveness 是他的回避态度；the evasiveness of the reply 是回答不肯直说的特点。它不必断言每句话都虚假，但会让人怀疑有所隐瞒。','his evasiveness；frustration at someone’s evasiveness；the evasiveness of an answer。','evasion 可数时常指一次回避或一句托词；evasiveness 把整体风格当作性质来谈。candour 则强调坦率，不绕开关键问题。',('Her evasiveness made the committee ask more questions.','她闪烁其词的态度让委员会追问了更多问题。'),('I was frustrated by the evasiveness of the official response.','官方答复回避重点，让我很失望。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/evasiveness','https://www.etymonline.com/word/evasive']),
E('invade','/ɪnˈveɪd/','入侵；侵入；侵扰','越过本来分开的边界，进入别人的领土、空间或生活。','拉丁 in- 向内 + vadere 走 → invadere，英语借入后保留闯入、侵犯的意味。这里的 in- 不是否定。',INV+[['拉丁 invadere → 英语 invade','敌对进入；扩展到侵扰空间、隐私等']],'invade a country 是入侵一个国家，invade someone’s privacy 是侵犯隐私。蚂蚁大量进厨房也可说 invade，带不受欢迎地涌入的感觉。','invade a country；invade someone’s privacy；invade personal space。','enter 只是进入；invade 常强调不受欢迎、越界或攻击。occupy 是占据，可以是入侵之后的状态，也有普通入住义。',('Ants had invaded the kitchen overnight.','一夜之间，蚂蚁涌进了厨房。'),('The camera angle seemed to invade her personal space.','那个拍摄角度仿佛侵入了她的私人空间。'),sources=['https://www.etymonline.com/word/invade','https://www.oxfordlearnersdictionaries.com/definition/english/invade']),
E('invasion','/ɪnˈveɪʒən/','入侵；侵袭；侵犯','把闯入这件事作为一个事件或过程来谈，从军队越境到隐私被打扰都能用。','英语经法语 invasion 接晚期拉丁 invasio、invasion-，来自 invadere 的分词词干。名词有独立借入线，不能一律说由现代 invade 加后缀才产生。',INV+[['晚期拉丁 invasio／invasion- → 法语 invasion → 英语 invasion','袭击、进入别人的领域；继而有侵犯权利等义']],'an invasion of a country 说明目标国家；an invasion of privacy 是侵犯隐私。the invasion of tourists 有时是夸张抱怨，不是实际军事行动。','a military invasion；an invasion of privacy；an invasion of insects。','invasion 侧重进入和侵入的事件；occupation 常侧重随后持续占领的状态。intrusion 可用于一次较小范围的闯入。',('The museum documents the invasion and the years that followed.','博物馆记录了那次入侵及其后的岁月。'),('Publishing the private messages was an invasion of privacy.','公开那些私人信息侵犯了隐私。'),sources=['https://www.etymonline.com/word/invasion','https://www.oxfordlearnersdictionaries.com/definition/english/invasion']),
E('invader','英 /ɪnˈveɪdə/；美 /ɪnˈveɪdər/','入侵者；侵入的生物或力量','从外面闯进来的那一方，可以是军队，也可以是外来生物或科幻里的外星人。','invade + -er，去掉末尾 e 后接表示行动者的后缀。',INV+[['拉丁 invadere → 英语 invade','进入、侵入'],['英语 invade + -er → invader','实施侵入的人或其他主体']],'foreign invaders 在历史叙述中常指外敌；an alien invader 在科幻里可能是外星入侵者。生物语境也可称某个入侵物种为 invader。','foreign invaders；alien invaders；repel the invaders。','invader 强调闯进来；intruder 可以是偷偷进入一间房的个人。visitor 通常只是来访者，没有入侵意味。',('The defenders forced the invaders to retreat.','守军迫使入侵者撤退。'),('The game asks players to defend Earth from alien invaders.','这款游戏让玩家保卫地球，抵御外星入侵者。'),sources=['https://www.etymonline.com/word/invader','https://www.oxfordlearnersdictionaries.com/definition/english/invader']),
E('invasive','/ɪnˈveɪsɪv/','侵入性的；侵扰的；有创的；具入侵性的','核心是越过边界往里进；在生态、隐私和医疗中，具体边界各不相同。','经法语 invasif 或直接接中世纪拉丁 invasivus；来自 invadere 的 invas- 分词词干。它有自己的古老借入线，不必先经过英语 invasion。',INV+[['拉丁 invas- → 中世纪拉丁 invasivus → 法语 invasif／英语 invasive','有侵入作用的；后来分出不同专业用法']],'invasive species 通常指在引入地区扩散并造成危害的外来种；invasive questions 指侵犯隐私的问题。invasive procedure 指需要进入身体内部等操作的检查或治疗；与肿瘤向邻近组织浸润的用法也应分清。','invasive species；an invasive procedure；invasive questions。','pervasive 是遍及、渗透很广；invasive 强调进入本不属于自己的范围。并非每个外来物种都一定是 invasive species。',('The invasive plant spread rapidly along the riverbank.','这种入侵植物沿河岸迅速蔓延。'),('She found the questions unnecessarily invasive.','她觉得那些问题没有必要地侵犯了隐私。'),sources=['https://www.etymonline.com/word/invasive','https://www.oxfordlearnersdictionaries.com/definition/english/invasive','https://www.invasivespeciesinfo.gov/what-are-invasive-species']),
E('pervasively','英 /pəˈveɪsɪvli/；美 /pərˈveɪsɪvli/','普遍地；广泛渗透地','影响不是落在一个角落，而是进入很多环节，到处都能感觉到。','pervasive + -ly。pervasive 往前接拉丁 pervadere 的 pervas-：per- 遍及 + vadere 走。',VAD+[['拉丁 per- + vadere → pervadere；pervas- → 英语 pervasive','走遍、贯穿 → 广泛存在的'],['英语 pervasive + -ly → pervasively','以广泛渗透的方式']],'pervasively used 表示广泛应用；pervasively corrupt 描述问题渗透许多层面。它常见于分析性文字，日常可以改说 widely 或 throughout。','pervasively used；pervasively corrupt；affect something pervasively。','widely 常只说范围广；pervasively 更突出分布在很多内部环节。invasively 则涉及侵入，不等于普遍存在。',('Digital tracking is now used pervasively across the advertising industry.','数字追踪如今广泛应用于整个广告行业。'),('The investigation described a pervasively corrupt system.','调查描述了一个腐败渗透各处的体系。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/pervasively','https://www.etymonline.com/word/pervasive']),
E('salubrious','/səˈluːbriəs/，也有 /səˈljuːbriəs/','有益健康的；环境宜人的','空气、环境或生活条件让人觉得清爽、舒服，适合好好生活。','拉丁 salubris 有益健康的，接 -ous 形成英语 salubrious；与 salus 健康、安好相连。并不是 salute 敬礼加后缀。',SAL+[['拉丁 salubris → 英语 salubrious','有益健康的；英语也用于舒适、体面的环境']],'a salubrious climate 是宜人的气候；salubrious surroundings 是良好环境。这个词偏正式，谈住处时也常带一点讲究或幽默。','a salubrious climate；salubrious surroundings；a less salubrious area。','healthy 可形容人本身健康；salubrious 更常说外部条件有利健康。salutary 则常说教训、提醒等虽不舒服却有益。',('They moved to a quieter, more salubrious neighbourhood.','他们搬到了更安静、环境更宜人的街区。'),('The brochure praises the town’s salubrious climate.','宣传册赞扬小镇宜人的气候。'),sources=['https://www.etymonline.com/word/salubrious','https://www.oxfordlearnersdictionaries.com/definition/english/salubrious','https://en.wiktionary.org/wiki/salubrious#English']),
E('insalubrious','/ˌɪnsəˈluːbriəs/','环境不佳的；不卫生的；不宜人的','一个住处或街区让人觉得脏、乱、阴暗，或不利健康；常是正式、略委婉的说法。','接拉丁 insalubris，或在英语 salubrious 前加否定 in-，两种分析并存。此处 in- 表示不，不是向内。',SAL+[['拉丁 salubris → insalubris，或英语 in- + salubrious → insalubrious','不利健康、环境不佳；不是先从 unsalubrious 改拼而来']],'insalubrious surroundings 是恶劣环境；an insalubrious hotel 可以含卫生差、环境不体面的意思。它不一定指已经有人生病，而是在评价条件。','insalubrious surroundings；an insalubrious district；insalubrious accommodation。','unhealthy 很直接，范围也更广；insalubrious 多用于场所和生活环境。salutary 的反面不靠把这个词随便替进去。',('The station stood in a rather insalubrious part of town.','车站坐落在城里一个环境相当差的地段。'),('The report criticised the workers’ insalubrious accommodation.','报告批评工人的住宿条件不卫生。'),sources=['https://www.etymonline.com/word/insalubrious','https://www.collinsdictionary.com/dictionary/english/insalubrious','https://dictionary.cambridge.org/pronunciation/english/insalubrious']),
]
