def rootwords(i,extra=()):return list(dict.fromkeys([w for w in ASSIGN['roots'][i]['family'] if w not in DEFERRED and '-' not in w]+list(extra)))
def rootexclude(i):
 r=CATALOG[ASSIGN['roots'][i]['id']];allwords=set(r['family'])|set(r['words'])|set(r['unmatched'])|set(ASSIGN['roots'][i]['family'])
 return {w:DEFERRED[w] for w in sorted(allwords) if w in DEFERRED}
HAL_ROOT=dict(id='C0520',meaning='呼吸；气息向内或向外',core='把气息当作有方向的流动：往里吸是 inhale，往外呼是 exhale。',image='拉丁 halare 呼吸 → inhalare／exhalare 两支；英语 inhalation 先出现，inhale 后反构或受法语和 exhale 对应关系影响；inhale → inhaler、inhalable；拉丁 inhalant- → inhalant。',intro='最实用的区别是行为、装置和物质：inhalation 是吸入，inhaler 是吸入器，inhalant 是吸入物。前缀的方向很好记，但历史不总按今天最短的词先出现；inhalation 的记录早于 inhale。',forms='hale 在这一族里读 /heɪl/，inhalation 的重音移到 -lation。拉丁 in- 原有向着、在……上的意思，英语 inhale 则明确表示吸入。-hel- 主要见于较古旧旁支，当前先掌握常用 hal- 词。',branches=[['吸入与呼出','inhale, inhalation, exhale, exhalation'],['吸入物与工具','inhaler, inhalant'],['能够吸入','inhalable']],contrasts='breathe 包括整个呼吸过程，inhale 与 exhale 分方向。inhalable 只说能被吸入，不等于适合呼吸。inhaler 装置、inhalant 物质、inhalation 行为不能互换。',practice='用 inhale 与 exhale 描写一次完整呼吸；用一句话区分 inhaler、inhalant、inhalation；解释为什么不能按现代拼写断言 inhale 比 inhalation 早。',words=rootwords(171),exclude=rootexclude(171))
SIT_ROOT=dict(id='C1354',meaning='食物；谷物',core='parasite 的原始画面是站在别人的饭桌旁吃饭，随后才走向依附和生物寄生。',image='希腊 sitos 谷物、食物 + para- 在旁 → parasitos；拉丁 parasitus／法语 parasite → 英语 parasite；希腊 parasitikos → 拉丁 parasiticus → parasitic；英语 parasite + -ism → parasitism。',intro='这根不等于英语 sit 坐。parasite 里 -sit- 来自食物，para- 是在旁；早期说靠别人供养的人，后来借这个关系描述寄生生物。parasite 是主体，parasitic 描述这种关系，parasitism 是生活关系的名称。',forms='parasite 词尾读 /saɪt/，parasitic、parasitism 的读音与重音会变化，见逐词音标。不要为了好记就编成坐在旁边的人；饭桌旁的联想成立，sit 坐的英语字源却不同。',branches=[['依靠别人而生活的主体','parasite'],['寄生、依附的特点','parasitic'],['寄生这一关系','parasitism']],contrasts='parasite 的宿主是 host；双方都获益的关系不能简单称寄生。比喻说人是 parasite 带很强贬义；生物学用法则描述关系，不是在给动物做道德评价。',practice='比较 parasite、parasitic、parasitism 的词性；用寄生植物说明宿主与寄生者；解释 parasite 为何不是 para + 英语 sit 坐。',words=rootwords(172),exclude=rootexclude(172))
VAD_ROOT=dict(id='C1600',meaning='走；前进；依方向变为逃出、侵入、遍及',core='同样是走，向外是逃开，向内是闯入，走遍各处则是遍及。',image='拉丁 vadere → ex-／e- + vadere → evadere、evasion- → evade、evasion、evasive；in- + vadere → invadere、invasion- → invade、invasion、invasive；per- + vadere → pervadere、pervas- → pervade、pervasive。',intro='evade 是躲开追捕或问题，invade 是越过边界侵入，pervade 是扩散到许多地方。vas- 只在这些复合词分词词干里与走相关；vasectomy 的 vas 是管道，另源，已有独立讲解。',forms='evade、invade 的 d 与 evasion、invasion、evasive、invasive 的 s 对应历史词干变化；不是英语随意换字母。evasion、invasion 各有名词借入路线，不要全排在现代动词之后。',branches=[['逃开与回避','evade, evasion, evasive, evasively, evasiveness'],['进入别人的范围','invade, invasion, invader, invasive, noninvasive'],['遍及内部各处','pervade, pervasive, pervasively, pervasiveness']],contrasts='invasive 强调越界进入，pervasive 强调分布广。evasive answer 是回避重点，vague answer 可能只是表达不清。vasectomy 的管道 vas 不是本根。',practice='比较 evade a question、invade privacy、pervade an organisation；把 evasive、evasion、evasiveness 放进不同句式；说明 invasive 与 pervasive 为什么不能互换。',words=rootwords(173,['pervade','noninvasive']),exclude=rootexclude(173))
SAL_ROOT=dict(id='C1251',meaning='健康；安好；福祉',core='愿你安好可以变成问候，对身体或处境有好处则通向健康、宜人和有益。',image='拉丁 salus，属格 salutis → salutare 祝安好 → salute；salutatio → salutation；salutaris → salutary；salubris → salubrious；insalubris 或 in- + salubrious → insalubrious。',intro='salute 不只军人敬礼，也可以郑重致意；salutation 是问候或信件称呼。salutary 常说有益的教训，salubrious 常说宜人的环境。它们共享安好的背景，却不能用一个中文好字到处替换。',forms='salu- 是根表的简写，历史实际还会见到 salut-、salubr-。salutary 并非由现代 salute 直接加 -ary；salubrious 也没有敬礼的意思。',branches=[['祝安好与问候','salute, salutation'],['带来良好作用','salutary'],['宜人与不宜人的环境','salubrious, insalubrious']],contrasts='salutary lesson 可能令人难受，却有益；salubrious surroundings 是环境舒服、有利健康。insalubrious 常评价环境，不是普通说一个人生病。',practice='用 salutation 描述邮件开头；比较 a salutary experience 与 salubrious surroundings；解释一个 unpleasant experience 为什么仍可能是 salutary。',words=rootwords(174,['salutation']),exclude=rootexclude(174))
NEB_ROOT=dict(id='C0800',meaning='云；雾；云的形状和色调',core='云可以让轮廓模糊，也可以让人看见颜色的微妙层次；这两种感觉分别帮助理解 nebulous 与 nuance。',image='拉丁 nebula → nebula、nebular；nebulosus → nebulous；nebula + -ize → nebulize → nebulizer。另一支拉丁 nubes → 法语 nue → nuer → nuance → nuanced。',intro='这页并列两条云词线，不把 nebula 与 nubes 硬接成前后代。nebula 是星云，nebulizer 制造细雾，nebulous 像雾一样模糊；nuance 却是色调或意义中可以细分的一点差别，nuanced 通常赞赏分析细致。',forms='nuance 的英式开头常有 /nj/，美式常为 /n/；nuanced 的 -ed 读 /t/。nebula 复数可写 nebulae 或 nebulas。nebulous 比现代天文名词 nebula 的常见借入形式更早，不能只按短词加后缀排历史。',branches=[['细微差别与层次','nuance, nuanced'],['模糊不清','nebulous'],['太空中的云','nebula, nebular'],['产生细雾的设备','nebulizer']],contrasts='nuanced 是细致有区分，nebulous 是轮廓不明。nebular 通常指星云相关；nebulous 不专指星云。nebulizer 不是一般空气加湿器的通用替名。',practice='分别用 nuanced 与 nebulous 评价一份计划；说清 nebula 与 galaxy 的区别；从云雾意象解释 nebulizer，又不把它当成太空装置。',words=rootwords(175),exclude=rootexclude(175))
CUB_ROOT=dict(id='C0283',meaning='骰子；立方块；三次方',core='一个六面方块，把几何体、体积单位和数的三次方连到一起；艺术词则借用几何块面的形象。',image='希腊 kybos 骰子 → 拉丁 cubus → 法语 cube／英语 cube；希腊 kybikos → 拉丁 cubicus → 法语 cubique → cubic；cube + -oid → cuboid；法语 cubisme → cubism，同一艺术命名背景下有 cubist。',intro='cube 可以是小方块，也可以是一个数的三次方；cubic 放在长度单位前表示体积。cuboid 通常是长方体。cubism 的立体主义则在画面里拆解和组合几何块面，并不意味着作品必须是一堆完美立方体。',forms='cubic 有早于现代 cube 拼写的独立借入历史，不能总画成英语 cube + -ic。cube 的动词过去式是 cubed，进行式 cubing。cubicle 小隔间接拉丁 cubare 躺，与这组方块根不同。',branches=[['几何形状与体积','cube, cubic, cuboid'],['艺术运动与艺术家','cubism, cubist']],contrasts='square 与 square metres 是平面、面积；cube 与 cubic metres 是立体、体积。cubist 是艺术风格，cubic 是几何或三次性质。普通 ice cube 不要求实际形状完全精确。',practice='说明边长两米的 cube 为什么有八 cubic metres；区分 cubism 与 cubist；对比 cubic sculpture 与 cubist sculpture。',words=rootwords(176),exclude=rootexclude(176))
GUST_ROOT=dict(id='C0508',meaning='尝；滋味；享受或反感',core='味道可以让人津津有味，也可以令人倒胃口；这种体验扩展到对行为和活动的态度。',image='拉丁 gustus、gustare → 意大利 gusto → 英语 gusto；gustatus + -ory → gustatory。法语 gouster 尝 → desgoust／desgouster → 英语 disgust 名词、动词 → disgusted、disgusting、disgustingly。',intro='gusto 是享受着做事的劲头，disgust 是强烈反感，gustatory 则平静地表示与味觉有关。英语 disgust 很早就有抽象厌恶义，味觉意象能帮助记忆，但不能冒充每个英语义项的严格先后。',forms='disgusted 的 -ed 读 /ɪd/，disgusting 的 -ing 读 /ɪŋ/。gust 一阵风另走日耳曼来源，不是拉丁 taste 的日常独立形式；不要凭拼写把风与味道混成一根。',branches=[['厌恶与使人厌恶','disgust, disgusted, disgusting, disgustingly'],['享受与热情','gusto'],['味觉关系词','gustatory']],contrasts='disgusted 是感受方，disgusting 是引发感受的一方。gusto 强调投入时的享受，不只是速度快。gustatory 味觉不同于 olfactory 嗅觉，也不同于 culinary 烹饪。',practice='用 disgusted 与 disgusting 描述同一场景的不同主体；把 with gusto 用在唱歌、吃饭和做事上；说明 disgustingly talented 为什么可能是玩笑式赞美。',words=rootwords(177),exclude=rootexclude(177))
